import { Form, Select } from '@/components/ui/form';
import { useUser } from '@/lib/auth';
import { ROLES } from '@/lib/authorization';
import { User } from '@/types/api';

import {
  updateUserRoleInputSchema,
  useUpdateUserRole,
} from '../api/update-user-role';

type UpdateUserRoleProps = {
  id: string;
  role: User['role'];
};

const ROLE_OPTIONS = [
  { label: ROLES.ADMIN, value: ROLES.ADMIN },
  { label: ROLES.USER, value: ROLES.USER },
];

export const UpdateUserRole = ({ id, role }: UpdateUserRoleProps) => {
  const user = useUser();
  const updateUserRoleMutation = useUpdateUserRole();

  return (
    <Form
      onSubmit={() => {}}
      schema={updateUserRoleInputSchema}
      options={{ defaultValues: { role: role as ROLES } }}
    >
      {({ register, formState }) => (
        <Select
          error={formState.errors['role']}
          options={ROLE_OPTIONS}
          registration={register('role', {
            disabled: updateUserRoleMutation.isPending || user.data?.id === id,
            onChange: (e) =>
              updateUserRoleMutation.mutate({
                userId: id,
                data: { role: e.target.value as ROLES },
              }),
          })}
        />
      )}
    </Form>
  );
};
E
